    c0, c1 = min(c for r, c in frame), max(c for r, c in frame)
    colors = {}
    opposite = {'TL': 'BR', 'BR': 'TL', 'TR': 'BL', 'BL': 'TR'}
    for r in range(len(grid)):
        for c in range(len(grid[0])):
